/**
 * @fileoverview Tests for no-unused-labels rule.
 * @author Toru Nagashima
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/no-unused-labels"),
	RuleTester = require("../../../lib/rule-tester/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const ruleTester = new RuleTester();

ruleTester.run("no-unused-labels", rule, {
	valid: [
		"A: break A;",
		"A: { foo(); break A; bar(); }",
		"A: if (a) { foo(); if (b) break A; bar(); }",
		"A: for (var i = 0; i < 10; ++i) { foo(); if (a) break A; bar(); }",
		"A: for (var i = 0; i < 10; ++i) { foo(); if (a) continue A; bar(); }",
		"A: { B: break B; C: for (var i = 0; i < 10; ++i) { foo(); if (a) break A; if (c) continue C; bar(); } }",
		"A: { var A = 0; console.log(A); break A; console.log(A); }",
	],
	invalid: [
		{
			code: "A: var foo = 0;",
			output: "var foo = 0;",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "A: { foo(); bar(); }",
			output: "{ foo(); bar(); }",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "A: if (a) { foo(); bar(); }",
			output: "if (a) { foo(); bar(); }",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "A: for (var i = 0; i < 10; ++i) { foo(); if (a) break; bar(); }",
			output: "for (var i = 0; i < 10; ++i) { foo(); if (a) break; bar(); }",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "A: for (var i = 0; i < 10; ++i) { foo(); if (a) continue; bar(); }",
			output: "for (var i = 0; i < 10; ++i) { foo(); if (a) continue; bar(); }",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "A: for (var i = 0; i < 10; ++i) { B: break A; }",
			output: "A: for (var i = 0; i < 10; ++i) { break A; }",
			errors: [{ messageId: "unused", data: { name: "B" } }],
		},
		{
			code: "A: { var A = 0; console.log(A); }",
			output: "{ var A = 0; console.log(A); }",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "A: /* comment */ foo",
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "A /* comment */: foo",
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},

		// https://github.com/eslint/eslint/issues/16988
		{
			code: 'A: "use strict"',
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: '"use strict"; foo: "bar"',
			output: null,
			errors: [{ messageId: "unused", data: { name: "foo" } }],
		},
		{
			code: 'A: ("use strict")', // Parentheses may be removed by another rule.
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "A: `use strict`", // `use strict` may be changed to "use strict" by another rule.
			output: null,
			languageOptions: { ecmaVersion: 6 },
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "if (foo) { bar: 'baz' }",
			output: "if (foo) { 'baz' }",
			errors: [{ messageId: "unused", data: { name: "bar" } }],
		},
		{
			code: "A: B: 'foo'",
			output: "B: 'foo'",
			errors: [
				{ messageId: "unused", data: { name: "A" } },
				{ messageId: "unused", data: { name: "B" } },
			],
		},
		{
			code: "A: B: C: 'foo'",
			output: "B: C: 'foo'", // Becomes "C: 'foo'" on the second pass.
			errors: [
				{ messageId: "unused", data: { name: "A" } },
				{ messageId: "unused", data: { name: "B" } },
				{ messageId: "unused", data: { name: "C" } },
			],
		},
		{
			code: "A: B: C: D: 'foo'",
			output: "B: D: 'foo'", // Becomes "D: 'foo'" on the second pass.
			errors: [
				{ messageId: "unused", data: { name: "A" } },
				{ messageId: "unused", data: { name: "B" } },
				{ messageId: "unused", data: { name: "C" } },
				{ messageId: "unused", data: { name: "D" } },
			],
		},
		{
			code: "A: B: C: D: E: 'foo'",
			output: "B: D: E: 'foo'", // Becomes "E: 'foo'" on the third pass.
			errors: [
				{ messageId: "unused", data: { name: "A" } },
				{ messageId: "unused", data: { name: "B" } },
				{ messageId: "unused", data: { name: "C" } },
				{ messageId: "unused", data: { name: "D" } },
				{ messageId: "unused", data: { name: "E" } },
			],
		},
		{
			code: "A: 42",
			output: "42",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},

		// Should not autofix if removing the label would create an ASI hazard
		{
			code: "foo()\nA: [1, 2, 3].forEach(x => x)",
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "foo()\nA: (function() {})()",
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "foo()\nA: /regex/.test(x)",
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "foo()\nA: +x",
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "foo()\nA: -x",
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "foo()\nA: `template` + bar",
			output: null,
			languageOptions: { ecmaVersion: 6 },
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},

		// Should not autofix if previous token is } (not always safe, e.g. function expression)
		{
			code: "const foo = function() {}\nA: [1, 2, 3].forEach(x => x)",
			output: null,
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},

		// Should autofix if previous statement ends safely (;, {, :)
		{
			code: "foo();\nA: [1, 2, 3].forEach(x => x)",
			output: "foo();\n[1, 2, 3].forEach(x => x)",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},
		{
			code: "OUTER: while (true) { A: [1, 2, 3].forEach(x => x); break OUTER; }",
			output: "OUTER: while (true) { [1, 2, 3].forEach(x => x); break OUTER; }",
			errors: [{ messageId: "unused", data: { name: "A" } }],
		},

		/*
		 * Below is fatal errors.
		 * "A: break B",
		 * "A: function foo() { break A; }",
		 * "A: class Foo { foo() { break A; } }",
		 * "A: { A: { break A; } }"
		 */
	],
});
